<?php
require_once 'includes/../includes/header.php';
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $name=trim($_POST['name']??''); $description=trim($_POST['description']??''); $locality=trim($_POST['locality']??''); $address=trim($_POST['address']??''); $cuisine=trim($_POST['cuisine']??''); $latitude=$_POST['latitude']!==''?(float)$_POST['latitude']:null; $longitude=$_POST['longitude']!==''?(float)$_POST['longitude']:null; $phone=trim($_POST['phone']??''); $image=trim($_POST['image']??''); $rating=$_POST['rating']!==''?(float)$_POST['rating']:null; $opening=$_POST['opening_time']?:null; $closing=$_POST['closing_time']?:null; $active=isset($_POST['is_active'])?1:0;
    if (!$name || !$description || !$locality || !$address || !$cuisine || ($image && !filter_var($image,FILTER_VALIDATE_URL))) $error='Complete the required fields and use a valid image URL.';
    else { $stmt=$pdo->prepare('INSERT INTO restaurants (name,description,locality,address,latitude,longitude,phone,image,cuisine,rating,opening_time,closing_time,is_active) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)'); $stmt->execute([$name,$description,$locality,$address,$latitude,$longitude,$phone,$image,$cuisine,$rating,$opening,$closing,$active]); redirect('restaurants.php'); }
}
$page_title='Add Restaurant';
?>
<div class="form-shell"><h1>Add restaurant</h1><?php if($error): ?><p class="error"><?= esc($error) ?></p><?php endif; ?><form method="post"><label>Name<input name="name" required></label><label>Description<textarea name="description" required></textarea></label><label>Locality<input name="locality" placeholder="Virudhunagar" required></label><label>Address<input name="address" required></label><div class="two-col"><label>Latitude<input name="latitude" type="number" step="any"></label><label>Longitude<input name="longitude" type="number" step="any"></label></div><label>Phone<input name="phone"></label><label>Cuisine<input name="cuisine" placeholder="Pizza, Burgers" required></label><label>Image URL<input name="image" type="url"></label><div class="two-col"><label>Opening time<input name="opening_time" type="time"></label><label>Closing time<input name="closing_time" type="time"></label></div><label>Rating<input name="rating" type="number" min="0" max="5" step="0.1"></label><label><input type="checkbox" name="is_active" checked style="width:auto"> Active</label><div class="form-actions"><button type="submit">Save Restaurant</button> <a class="button secondary" href="restaurants.php">Cancel</a></div></form></div><?php include 'includes/footer.php'; ?>
